mapper.select:
SELECT address_id, member_id, address_name, receiver_name, receiver_phone,
       postal_code, address, address_detail, is_default
FROM ADDRESS
WHERE address_id = #{addressId}
  AND member_id = #{memberId}

SELECT EXISTS (
    SELECT 1 FROM ADDRESS WHERE member_id = #{memberId}
)

mapper.insert:
INSERT INTO ADDRESS (
    member_id, address_name, receiver_name, receiver_phone,
    postal_code, address, address_detail, is_default
) VALUES (
    #{memberId}, #{addressName}, #{receiverName}, #{receiverPhone},
    #{postalCode}, #{address}, #{addressDetail}, #{isDefault}
)

mapper.update:
UPDATE ADDRESS
SET address_name   = #{addressName},
    receiver_name  = #{receiverName},
    receiver_phone = #{receiverPhone},
    postal_code    = #{postalCode},
    address        = #{address},
    address_detail = #{addressDetail}
WHERE address_id = #{addressId}
  AND member_id = #{memberId}

mapper.delete:
DELETE FROM ADDRESS
WHERE address_id = #{addressId}
  AND member_id = #{memberId}

mapper.update:
UPDATE ADDRESS
SET is_default = 1
WHERE address_id = #{addressId}
  AND member_id = #{memberId}
